import re
from datetime import date, datetime
from types import SimpleNamespace
from rapidfuzz import fuzz, process, utils   # pip install rapidfuzz

# --- 1) normalise values BEFORE rules and scoring ---
def norm_amount(text: str) -> float:
    s = re.sub(r"[^\d,.\-]", "", text)          # drop currency symbols and spaces
    if "," in s and s.rfind(",") > s.rfind("."):
        s = s.replace(".", "").replace(",", ".")  # European: 1.250,00 -> 1250.00
    else:
        s = s.replace(",", "")                   # US/UK: 1,250.00 -> 1250.00
    return float(s)

def norm_date(text: str, locale: str) -> str:
    fmt = {"US": "%m/%d/%Y", "EU": "%d/%m/%Y"}[locale]   # 03/10 differs by country
    return datetime.strptime(text, fmt).date().isoformat()

print(norm_amount("€ 1.250,00"), norm_amount("$1,250.00"))  # 1250.0 1250.0
print(norm_date("03/10/2026", "US"), norm_date("03/10/2026", "EU"))  # 2026-03-10 2026-10-03

# --- 2) match supplier names to the master list, then use the id ---
suppliers = {"S-100": "Brambleway Tools Ltd", "S-200": "Keelstone Fasteners GmbH"}

def supplier_id(name: str | None, min_score: int = 90) -> str | None:
    if not name:
        return None
    hit = process.extractOne(name, suppliers, scorer=fuzz.token_sort_ratio,
                             processor=utils.default_process)   # lowercases, drops punctuation
    return hit[2] if hit and hit[1] >= min_score else None      # hit = (name, score, id)

print(supplier_id("BRAMBLEWAY TOOLS LTD."), supplier_id("Brambleway Timber"))  # S-100 None

def review_reasons(inv, line_totals: list[float]) -> list[str]:
    reasons = []
    if inv.total is None or inv.invoice_number is None:
        reasons.append("missing required field")
    if inv.total is not None and abs(sum(line_totals) - inv.total) > 0.01:
        reasons.append("line items do not add up")
    if inv.invoice_date and inv.invoice_date > date.today().isoformat():
        reasons.append("date in the future")
    if supplier_id(inv.supplier_name) is None:   # resolve the NAME to an id first
        reasons.append("unknown supplier")
    return reasons           # empty list: auto-approve; else human queue

inv = SimpleNamespace(invoice_number="7781", total=66.0, invoice_date="2026-09-14",
                      supplier_name="Brambleway Tools Ltd.")
print(review_reasons(inv, [50.0, 16.0]))         # []

# --- 3) score accuracy on normalised values, not raw strings ---
def same(field, p, g):
    if p is None or g is None:
        return p == g
    if field == "supplier_name":
        return supplier_id(p) is not None and supplier_id(p) == supplier_id(g)
    if field == "total":
        return abs(norm_amount(str(p)) - norm_amount(str(g))) < 0.005
    return utils.default_process(str(p)) == utils.default_process(str(g))

def field_accuracy(preds: list[dict], gold: list[dict], field: str) -> float:
    hits = sum(same(field, p.get(field), g.get(field)) for p, g in zip(preds, gold))
    return hits / len(gold)

preds = [{"supplier_name": "BRAMBLEWAY TOOLS LTD.", "total": "1.250,00"}]
gold  = [{"supplier_name": "Brambleway Tools Ltd",  "total": "1250.00"}]
print(field_accuracy(preds, gold, "supplier_name"), field_accuracy(preds, gold, "total"))  # 1.0 1.0

