CREATE CONSTRAINT company_name IF NOT EXISTS FOR (c:Company) REQUIRE c.name IS UNIQUE;
CREATE CONSTRAINT part_name    IF NOT EXISTS FOR (p:Part)    REQUIRE p.name IS UNIQUE;

// Bulk load the ERP supplier table (CSV must sit in Neo4j's import folder)
LOAD CSV WITH HEADERS FROM 'file:///supplier_parts.csv' AS row
MERGE (c:Company {name: row.supplier_name})
  SET c.erp_id = row.supplier_id, c.country = row.country
MERGE (p:Part {name: row.part_name})
MERGE (c)-[r:SUPPLIES]->(p)
  SET r.source = 'erp:supplier_parts', r.loaded_at = datetime();

