from neo4j import GraphDatabase

driver = GraphDatabase.driver("neo4j://graph-host:7687", auth=("reader_writer", "PASSWORD"))

def refresh_document(doc_id: str, text: str):
    facts = extract_facts(text)          # extract FIRST, so a failure leaves the old edges in place
    def work(tx):
        tx.run("MATCH ()-[r {source: $doc}]->() DELETE r", doc=doc_id)
        for f in facts:                  # relation names come from a fixed list, never from user text
            assert f["relation"] in {"SUPPLIES", "PART_OF", "LOCATED_IN"}
            tx.run(f"MERGE (a:Entity {{name: $s}}) MERGE (b:Entity {{name: $o}}) "
                   f"MERGE (a)-[r:{f['relation']} {{source: $doc}}]->(b)",
                   s=normalise(f["subject"]), o=normalise(f["object"]), doc=doc_id)
    with driver.session() as session:
        session.execute_write(work)      # delete and reload happen in one transaction

