import json
from datetime import datetime, timezone

PAUSED = {"claims-assistant": False}          # in real life: a feature flag or config service

def pause(system: str, reason: str, who: str):
    PAUSED[system] = True                      # the pause switch: every request checks this first
    log_incident(system, "paused", reason, who)

def handle_request(system: str, question: str) -> str:
    if PAUSED.get(system):
        return "This assistant is switched off right now. A team member will help you."
    return "...normal answer..."

def log_incident(system, event, detail, who):
    record = {"time": datetime.now(timezone.utc).isoformat(timespec="seconds"), "system": system,
              "event": event, "detail": detail, "by": who}
    print(json.dumps(record))                  # in real life: the incident tracker

pause("claims-assistant", "Gave a wrong deadline to 12 customers", "on-call-lead")
print(handle_request("claims-assistant", "When is my claim due?"))
